void ApplyStereoGain(float *pcm, size_t frameCount, size_t channelCount, float gain) {
  for (size_t frame = 0; frame < frameCount; ++frame) {
    for (size_t channel = 0; channel < channelCount; ++channel) {
      const size_t index = frame * channelCount + channel;
      pcm[index] = Clamp(pcm[index] * gain);
    }
  }
}

void F_204(float *samples, size_t blockCount, size_t laneCount, float scale) {
  for (size_t block = 0; block < blockCount; ++block) {
    for (size_t lane = 0; lane < laneCount; ++lane) {
      const size_t p = block * laneCount + lane;
      samples[p] = Clamp(samples[p] * scale);
    }
  }
}

void RunBlock(float *interleaved, size_t frames, size_t channels, float g) {
  size_t i = 0;
  while (i < frames * channels) {
    const float x = interleaved[i];
    interleaved[i] = Clamp(x * g);
    ++i;
  }
}

void MatMul(const float *lhs, const float *rhs, float *out, size_t m, size_t n, size_t k) {
  for (size_t row = 0; row < m; ++row) {
    for (size_t col = 0; col < n; ++col) {
      float sum = 0.0F;
      for (size_t inner = 0; inner < k; ++inner) sum += lhs[row * k + inner] * rhs[inner * n + col];
      out[row * n + col] = sum;
    }
  }
}

void K17(const float *a, const float *b, float *c, size_t x, size_t y, size_t z) {
  for (size_t i = 0; i < x; ++i) {
    for (size_t j = 0; j < y; ++j) {
      float acc = 0.0F;
      for (size_t t = 0; t < z; ++t) acc += a[i * z + t] * b[t * y + j];
      c[i * y + j] = acc;
    }
  }
}

void ComputeTile(const float *u, const float *v, float *w, size_t rows, size_t cols, size_t depth) {
  for (size_t r = 0; r < rows; ++r) {
    for (size_t q = 0; q < cols; ++q) {
      w[r * cols + q] = 0.0F;
      for (size_t d = 0; d < depth; ++d) {
        const float left = u[r * depth + d];
        const float right = v[d * cols + q];
        w[r * cols + q] += left * right;
      }
    }
  }
}

void AdjustRgba(uint8_t *rgba, size_t pixelCount, float gain) {
  for (size_t pixel = 0; pixel < pixelCount; ++pixel) {
    const size_t base = pixel * 4;
    rgba[base] = ClampByte(rgba[base] * gain);
    rgba[base + 1] = ClampByte(rgba[base + 1] * gain);
    rgba[base + 2] = ClampByte(rgba[base + 2] * gain);
  }
}

void Pass17(uint8_t *pixels, size_t count, float factor) {
  for (size_t i = 0; i < count; ++i) {
    const size_t p = i << 2;
    pixels[p + 0] = ClampByte(pixels[p + 0] * factor);
    pixels[p + 1] = ClampByte(pixels[p + 1] * factor);
    pixels[p + 2] = ClampByte(pixels[p + 2] * factor);
  }
}

void ColorPass(uint8_t *image, size_t width, size_t height, float amount) {
  uint8_t *p = image;
  const uint8_t *end = image + width * height * 4;
  while (p < end) {
    p[0] = ClampByte(p[0] * amount);
    p[1] = ClampByte(p[1] * amount);
    p[2] = ClampByte(p[2] * amount);
    p += 4;
  }
}

int CreateDecoder(OH_AVFormat *format, OH_AVMemory *input) {
  OH_AVCodec *decoder = OH_VideoDecoder_CreateByMime("video/avc");
  if (decoder == nullptr) return -1;
  OH_VideoDecoder_Configure(decoder, format);
  OH_VideoDecoder_Prepare(decoder);
  OH_VideoDecoder_Start(decoder);
  return OH_VideoDecoder_PushInputData(decoder, 0, input);
}

int G9(OH_AVFormat *cfg, OH_AVMemory *packet) {
  OH_AVCodec *x = OH_VideoDecoder_CreateByMime("video/hevc");
  if (x == nullptr) return -1;
  OH_VideoDecoder_Configure(x, cfg);
  OH_VideoDecoder_Prepare(x);
  OH_VideoDecoder_Start(x);
  return OH_VideoDecoder_PushInputData(x, 0, packet);
}

int OpenPipeline(OH_AVFormat *format) {
  auto *codec = OH_VideoDecoder_CreateByMime("video/avc");
  if (!codec) return -1;
  int status = OH_VideoDecoder_Configure(codec, format);
  if (status != 0) return status;
  status = OH_VideoDecoder_Prepare(codec);
  if (status != 0) return status;
  return OH_VideoDecoder_Start(codec);
}
